/// <reference types="vite/client" />
import { JLPTLevel, SubtitleLineRecord, SubtitleTokenJSON } from '../../schema/databaseSchema';

/**
 * Real timed captions generated by scripts/fetch-captions.py (one file per youtube_id).
 */
interface CaptionLine {
  start_ms: number;
  end_ms: number;
  ja: string | null;
  th: string | null;
}

interface CaptionFile {
  youtube_id: string;
  source: { ja: string; th: string };
  lines: CaptionLine[];
}

const captionModules = import.meta.glob('./*.json', { eager: true }) as Record<
  string,
  { default: CaptionFile }
>;

const CAPTIONS_BY_ID: Record<string, CaptionFile> = {};
for (const mod of Object.values(captionModules)) {
  const file = mod.default;
  if (file && file.youtube_id) CAPTIONS_BY_ID[file.youtube_id] = file;
}

export const getRealCaptions = (youtubeId: string): CaptionFile | undefined =>
  CAPTIONS_BY_ID[youtubeId];

// Splits Japanese text on whitespace and punctuation. Pieces that contain no
// letters/kana/kanji (pure punctuation) are dropped.
const splitJapanese = (text: string): string[] =>
  text
    .split(/[\s、。！？!?,.「」『』（）()［］\[\]【】…・〜~「」"'“”‘’:：;；]+/)
    .filter((part) => part.length > 0 && /[\p{L}\p{N}]/u.test(part));

const buildTokens = (
  youtubeId: string,
  lineIndex: number,
  ja: string,
  jlpt: JLPTLevel
): SubtitleTokenJSON[] =>
  splitJapanese(ja).map((surface, tokenIndex) => ({
    surface,
    word_id: `cap-${youtubeId}-${lineIndex}-${tokenIndex}`,
    lemma: surface,
    reading_kana: surface,
    romaji: '',
    jlpt_level: jlpt,
    part_of_speech: '',
    contextual_meaning: '',
  }));

/**
 * Builds SubtitleLineRecord[] for a video from its real captions.
 * Returns undefined when no caption file exists for the youtube_id (caller falls back).
 * Lines with no Japanese text get tokens_json = [] and raw_text = ''.
 */
export const buildRealSubtitleLines = (
  youtubeId: string,
  videoId: string,
  jlpt: JLPTLevel
): SubtitleLineRecord[] | undefined => {
  const file = getRealCaptions(youtubeId);
  if (!file) return undefined;

  return file.lines.map((line, i) => {
    const ja = line.ja ?? '';
    const th = line.th ?? undefined;
    return {
      id: `cap-${youtubeId}-${i}`,
      video_id: videoId,
      line_index: i,
      start_time_ms: line.start_ms,
      end_time_ms: line.end_ms,
      raw_text: ja,
      natural_translation: th ?? '',
      thai_translation: th,
      ai_grammar_summary: '',
      tokens_json: ja ? buildTokens(youtubeId, i, ja, jlpt) : [],
    };
  });
};
